<?php
header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store, no-cache, must-revalidate'); include 'conn.php';
$type=(string)($_GET['type']??'');$period=trim((string)($_GET['periodid']??''));$gameMap=array('wingo30'=>'WinGo_30S','wingo1'=>'WinGo_1M','wingo3'=>'WinGo_3M','wingo5'=>'WinGo_5M','k31'=>'K3_1M','k33'=>'K3_3M','k35'=>'K3_5M','k310'=>'K3_10M','5d1'=>'D5_1M','5d3'=>'D5_3M','5d5'=>'D5_5M','5d10'=>'D5_10M','ktrx'=>'TrxWinGo_1M','ktrx3'=>'TrxWinGo_3M','ktrx5'=>'TrxWinGo_5M','ktrx10'=>'TrxWinGo_10M','motoracing'=>'MotoRace_1M');
if(!isset($gameMap[$type])||!preg_match('/^[0-9]{17}$/',$period)){http_response_code(400);echo json_encode(array('data'=>array()));exit;}$summary=array();
try{$stmt=$conn->prepare('SELECT b.bet_content,COUNT(DISTINCT b.user_id) users,COALESCE(SUM(b.stake),0) stake FROM saas_lottery_bets b LEFT JOIN demo d ON d.balakedara=b.user_id WHERE b.game_code=? AND b.issue_number=? AND d.balakedara IS NULL GROUP BY b.bet_content ORDER BY stake DESC,b.bet_content');$stmt->bind_param('ss',$gameMap[$type],$period);$stmt->execute();$result=$stmt->get_result();while($result&&($row=$result->fetch_assoc())){$bet=(string)$row['bet_content'];$stake=(float)$row['stake'];$rate=0.0;if(stripos($bet,'Num_')===0)$rate=9.0;elseif(stripos($bet,'Color_Violet')===0)$rate=4.5;elseif(stripos($bet,'Color_')===0||stripos($bet,'BigSmall_')===0)$rate=2.0;$summary[]=array('bet'=>$bet,'users'=>(int)$row['users'],'stake'=>$stake,'potentialPayout'=>round($stake*$rate*.98,2));}$stmt->close();}catch(Throwable $e){error_log('[admin bet summary] '.$e->getMessage());}echo json_encode(array('data'=>$summary),JSON_UNESCAPED_SLASHES);
